/*
 * A183209  Tree generated by floor(3n/2): a(1) = 1, a(2n) = (3*a(n))-1,
 *          a(2n+1) = floor((3*a(n+1))/2).
 * https://oeis.org/A183209
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf, look
 * Formula:   a(1) = 1; a(2n) = 3*a(n) - 1; a(2n+1) = floor((3*a(n+1))/2); for
 *            every n >= 1
 * Range:     u8 n <= 63, u16 n <= 2047, u32 n <= 8192, u64 n <= 8192,
 *            u128 n <= 8192, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* Handle the trivial case.  The sequence is 1‑indexed, so
       n = 0 is out of range and is returned as 0. */
    if (n == 0)
        return (seq_t)0;

    /* Static cache for memoisation.  cache[0] is unused. */
    static seq_t *cache = NULL;
    static idx_t cache_size = 0;      /* current allocated size */

    /* Expand the cache if necessary. */
    if (n+1 > cache_size) {
        idx_t new_size = n + 1;
        seq_t *tmp = (seq_t *)realloc(cache, new_size * sizeof(seq_t));
        if (!tmp)
            return (seq_t)0;          /* allocation failed – unlikely in tests */
        cache = tmp;

        /* Initialise fresh entries. */
        for (idx_t i = cache_size; i < new_size; ++i) {
            if (i == 0)          /* unused */
                continue;
            if (i == 1) {
                cache[i] = (seq_t)1;
            } else if ((i & 1) == 0) {   /* even index */
                cache[i] = (seq_t)3 * cache[i/2] - (seq_t)1;
            } else {                     /* odd index */
                cache[i] = ((seq_t)3 * cache[(i+1)/2]) / (seq_t)2;
            }
        }
        cache_size = new_size;
    }
    return cache[n];
}
